import React from 'react';
import './Products.css';

const Products = () => {
  const products = [
    {
      id: 1,
      name: "AquaShield Interior",
      description: "Premium water-based paint for interior walls with anti-bacterial properties",
      features: ["Zero VOC", "Quick Dry", "Washable", "Anti-Bacterial"],
      color: "#FF6B6B",
      icon: "🏠"
    },
    {
      id: 2,
      name: "WeatherGuard Exterior",
      description: "Weather-resistant exterior paint that protects against harsh conditions",
      features: ["UV Protection", "Waterproof", "Fade Resistant", "10 Year Warranty"],
      color: "#4ECDC4",
      icon: "🌤️"
    },
    {
      id: 3,
      name: "EcoKids Safe Paint",
      description: "Child-safe paint perfect for nurseries and playrooms",
      features: ["Non-Toxic", "Odorless", "Easy Cleanup", "Bright Colors"],
      color: "#45B7D1",
      icon: "👶"
    },
    {
      id: 4,
      name: "ProFinish Premium",
      description: "Professional-grade paint for commercial and high-traffic areas",
      features: ["High Durability", "Stain Resistant", "Low Maintenance", "Smooth Finish"],
      color: "#96CEB4",
      icon: "🏢"
    }
  ];

  return (
    <section className="products section" id="products">
      <div className="container">
        <div className="section-header">
          <h2 className="section-title">Our Paint Products</h2>
          <p className="section-subtitle">Discover our range of eco-friendly water-based paints</p>
        </div>

        <div className="products-grid">
          {products.map((product) => (
            <div key={product.id} className="product-card">
              <div className="product-icon" style={{ backgroundColor: product.color }}>
                <span>{product.icon}</span>
              </div>

              <h3 className="product-name">{product.name}</h3>
              <p className="product-description">{product.description}</p>

              <div className="product-features">
                {product.features.map((feature, idx) => (
                  <span key={idx} className="feature-tag">{feature}</span>
                ))}
              </div>

              <button className="btn product-btn">Learn More</button>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default Products;
